#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-03-24

# Validate that rule references in test-cases.json point to actual rule files
# Catches mismatches like "contract-pact" when actual file is "verification-contract.md"
#
# Exit codes:
#   0 - All rule references valid
#   1 - Invalid test-case files or missing rule files detected

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
SKILLS_DIR="$PROJECT_ROOT/src/skills"

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

ERRORS=0

for test_file in "$SKILLS_DIR"/*/test-cases.json; do
  [[ ! -f "$test_file" ]] && continue
  skill_dir=$(dirname "$test_file")
  skill_name=$(basename "$skill_dir")
  rules_dir="$skill_dir/rules"

  # Extract rule values from testCases[].rule (skip null/empty)
  if ! rules=$(node -e '
    let d;
    try {
      d = require(process.argv[1]);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      console.log("invalid JSON");
      process.exit(1);
    }
    const key = d?.testCases !== undefined ? "testCases" :
      d?.test_cases !== undefined ? "test_cases" : null;
    const cases = key ? d[key] : (Array.isArray(d) ? d : []);
    if (!Array.isArray(cases)) {
      console.log(`${key} must be an array`);
      process.exit(1);
    }
    const rules = cases.map(c => c.rule).filter(rule => rule && rule !== "null");
    rules.forEach(rule => console.log(rule));
  ' "$test_file"); then
    echo -e "  ${RED}✗${NC} src/skills/$skill_name/test-cases.json: ${rules:-could not extract rule references}"
    ERRORS=$((ERRORS + 1))
    continue
  fi

  for rule in $rules; do
    [[ -z "$rule" ]] && continue
    rule_file="$rules_dir/$rule.md"
    if [[ ! -f "$rule_file" ]]; then
      echo -e "  ${RED}✗${NC} $skill_name: rule '$rule' in test-cases.json but rules/$rule.md not found"
      ERRORS=$((ERRORS + 1))
    fi
  done
done

if [[ "$ERRORS" -gt 0 ]]; then
  echo ""
  echo -e "${RED}Rule reference validation FAILED: $ERRORS error(s)${NC}"
  exit 1
fi

echo -e "  ${GREEN}✓${NC} All test-cases.json rule references match actual files"
exit 0
